/bin/bash -lc "node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'launch.sqlite') },
  detached: true, stdio: ['ignore', 'pipe', 'pipe'],
});
try {
  const url = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Launch timed out')), 5000);
    child.stdout.on('data', (data) => {
      const match = data.toString().match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timer); resolve("'`http://127.0.0.1:${match[1]}`); }
    });
    child.once('"'error', reject);
  });
  const response = await fetch("'`${url}/health`);
  if (response.status !== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') {
    throw new Error('Health check failed');
  }
  console.log('npm start with PORT and DB_PATH: health check passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
EOF"

